import{_ as t,c as r,o as a,a3 as s}from"./chunks/framework.Dokpd4od.js";const m=JSON.parse('{"title":"Purchase templates","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/orders/purchase-templates.md","filePath":"master/supply-chain/purchase/orders/purchase-templates.md","lastUpdated":1792041590000}'),o={name:"master/supply-chain/purchase/orders/purchase-templates.md"};function n(l,e,i,d,h,u){return a(),r("div",null,e[0]||(e[0]=[s('<h1 id="purchase-templates" tabindex="-1">Purchase templates <a class="header-anchor" href="#purchase-templates" aria-label="Permalink to &quot;Purchase templates&quot;">​</a></h1><p>A purchase template is a saved set of product lines for a vendor. You build it once, then reuse it whenever you reorder the same items. It has no validity dates and no quantity limit.</p><blockquote><p><strong>In simple words:</strong> A template is a ready-made shopping list for a vendor. Pick it on a new RFQ and the lines appear.</p></blockquote><p>Open <code>Purchase → Orders → Purchase Agreements</code> and click the <strong>Purchase Templates</strong> tab.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Templates share the <strong>Purchase Agreements</strong> setting with blanket orders. Go to <code>Purchase → Settings → Manage Orders</code> and switch on <strong>Purchase Agreements</strong>. See <a href="./../get-started/purchase-settings.html">Purchase settings</a>.</p><h2 id="template-or-blanket-order" tabindex="-1">Template or blanket order <a class="header-anchor" href="#template-or-blanket-order" aria-label="Permalink to &quot;Template or blanket order&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Purchase template</th><th>Blanket order</th></tr></thead><tbody><tr><td>Purpose</td><td>Reuse the same lines</td><td>Commit to a total quantity</td></tr><tr><td><strong>Valid From</strong>, <strong>Valid Until</strong></td><td>Hidden</td><td>Required</td></tr><tr><td><strong>Ordered</strong> column</td><td>Hidden</td><td>Shows quantity already ordered</td></tr><tr><td>Quantity limit on RFQs</td><td>None</td><td>Yes</td></tr><tr><td>Reference on documents</td><td><strong>PT/</strong> and a number</td><td><strong>BO/</strong> and a number</td></tr></tbody></table><p>See <a href="./blanket-orders.html">Blanket orders</a> for the other type.</p><h2 id="create-a-template" tabindex="-1">Create a template <a class="header-anchor" href="#create-a-template" aria-label="Permalink to &quot;Create a template&quot;">​</a></h2><p>Example: you reorder 20 <strong>SSD 512GB</strong> from FreshFoods Wholesale every month.</p><ol><li>Click <strong>New Purchase Agreement</strong>.</li><li>Fill the top section.</li></ol><ul><li><strong><em>Vendor:</em></strong> Required. The supplier you buy from.</li><li><strong><em>Buyer:</em></strong> The user in charge.</li><li><strong><em>Agreement Type:</em></strong> Required. Choose <strong>Purchase Template</strong>. The date fields disappear.</li><li><strong><em>Currency:</em></strong> Required. Starts with your company currency.</li><li><strong><em>Reference:</em></strong> Your own note.</li><li><strong><em>Company:</em></strong> Required. Starts with your current company.</li></ul><ol start="3"><li>On the <strong>Products</strong> tab, add a line for each product.</li></ol><ul><li><strong><em>Product:</em></strong> Required. Goods products only.</li><li><strong><em>Quantity:</em></strong> Required. The quantity you usually buy.</li><li><strong><em>Unit of Measure:</em></strong> Shown only when <strong>Unit of Measure</strong> is on in <strong>Manage Products</strong>.</li><li><strong><em>Unit Price:</em></strong> Required. The price you expect to pay.</li></ul><ol start="4"><li>Click <strong>Create</strong>. The template starts as <strong>Draft</strong>.</li></ol><h2 id="confirm-and-use-a-template" tabindex="-1">Confirm and use a template <a class="header-anchor" href="#confirm-and-use-a-template" aria-label="Permalink to &quot;Confirm and use a template&quot;">​</a></h2><ol><li>Open the template and click <strong>Confirm</strong>. It needs at least one line.</li><li>Click <strong>New RFQ</strong> and pick the same <strong>Vendor</strong>.</li><li>Open the <strong>Agreement</strong> list and choose the template. It offers confirmed agreements only.</li><li>Aureus fills the product lines and the <strong>Currency</strong>. Change quantities if you need to.</li><li>Click <strong>Create</strong> and continue as with any <a href="./quotations.html">request for quotation</a>.</li></ol><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>A template uses the same states and buttons as a blanket order: <strong>Draft</strong>, <strong>Confirmed</strong>, <strong>Closed</strong>, <strong>Canceled</strong>. The buttons are <strong>Confirm</strong>, <strong>Close</strong>, <strong>Cancel</strong>, <strong>Print</strong> and <strong>Delete</strong>. See <a href="./blanket-orders.html#actions-and-statuses">Blanket orders</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>Close</strong> when a template is out of date. Close is blocked while related RFQs are still open.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./blanket-orders.html">Blanket orders</a></li><li><a href="./quotations.html">Requests for quotation</a></li><li><a href="./purchase-orders.html">Purchase orders</a></li><li><a href="./../get-started/purchase-settings.html">Purchase settings</a></li></ul>',23)]))}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
